#[cfg(test)]
pub fn put_referenceAndFdState(value: *mut FlightStack::ReferenceAndFdState) -> bool
{
  unsafe {
    *OUT_referenceAndFdState.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
